<div class="support-widget" id="support-widget">
  <button class="support-launcher" id="support-launcher" aria-label="Open support chat" aria-controls="support-panel" aria-expanded="false"><span class="support-launcher-icon" aria-hidden="true">✳</span><span>Need a hand?</span><span class="support-launcher-arrow" aria-hidden="true">↗</span></button>
  <section class="support-panel" id="support-panel" role="dialog" aria-labelledby="support-title" hidden>
    <header class="support-heading"><span class="support-mark" aria-hidden="true">✳</span><div><span class="support-eyebrow">EDGE / HERE TO HELP</span><h2 id="support-title">Your support line<span>.</span></h2></div><button class="support-close" id="support-close" aria-label="Close support chat">×</button></header>
    <div class="support-statusbar"><span class="status-dot" aria-hidden="true"></span><span id="support-status">Automated support</span><span id="support-question-count"></span></div>
    <div class="support-chat-body" id="support-chat-body"><div id="support-guest" class="support-empty" hidden></div><div id="support-customer-thread"><button class="support-older" id="support-load-older" hidden>Load earlier messages ↑</button><div class="support-messages" id="support-messages" role="log" aria-label="Support conversation" aria-live="polite" aria-relevant="additions text"></div><div id="support-thinking" class="support-thinking" role="status" hidden><i></i><i></i><i></i><span>Preparing your answer…</span></div><div class="support-quick" id="support-quick" aria-label="Quick account questions"></div></div></div>
    <div class="support-error" id="support-error" role="alert" hidden></div>
    <div class="support-footer" id="support-footer"><div class="support-transfer"><span id="support-assistant-label">Built-in account assistant</span><button id="support-handover" type="button">Talk to admin ↗</button></div><form id="support-chat-form"><label class="support-sr-only" for="support-input">Your message to support</label><textarea id="support-input" name="body" rows="2" maxlength="2000" placeholder="Ask about your account…" required></textarea><button id="support-send" type="submit" aria-label="Send support message"><svg aria-hidden="true"><use href="#i-arrow"/></svg></button></form><button class="support-new button green" id="support-new" hidden>Start a new conversation ↗</button><p class="support-privacy" id="support-privacy">Account help, then a human handover. Never share passwords, card details or identity documents here.</p></div>
  </section>
</div>

<template id="support-admin-template">
  <div class="admin-tab-panel" id="admin-support-tab" role="tabpanel" aria-labelledby="admin-tab-support" hidden>
    <div class="admin-content-heading"><div><span class="section-kicker">A HUMAN ON YOUR SIDE / SUPPORT</span><h2>The support line<span>.</span></h2><p>Pick up where the account assistant leaves off. Claim a conversation before replying.</p></div><button class="button outline" id="support-inbox-refresh">Refresh inbox <svg aria-hidden="true"><use href="#i-clock"/></svg></button></div>
    <div class="support-inbox-toolbar"><label for="support-inbox-filter">Show conversations<select id="support-inbox-filter"><option value="waiting">Waiting for admin</option><option value="admin">Admin connected</option><option value="bot">Automated support</option><option value="resolved">Resolved</option><option value="all">All conversations</option></select></label><span id="support-inbox-count"></span></div>
    <div class="support-error" id="support-admin-error" role="alert" hidden></div>
    <div class="support-inbox"><aside class="support-inbox-rail" aria-label="Support conversations"><div id="support-inbox-list"></div><div class="support-pagination" id="support-inbox-pagination" hidden><button data-support-page="previous">← Previous</button><span id="support-inbox-page"></span><button data-support-page="next">Next →</button></div></aside><section class="support-admin-thread" id="support-admin-thread" aria-label="Selected support conversation"><div class="support-inbox-empty"><span aria-hidden="true">↗</span><h3>Make the next connection.</h3><p>Choose a conversation to read the account assistant’s messages and help the user.</p></div></section></div>
    <p class="support-inbox-note">Support messages cannot approve verification, move funds or settle games. Use the corresponding admin desk for account changes.</p>
  </div>
</template>
